package com.cinebooking.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payment")
public class Payment {
 @Id private UUID id; @Column(name="booking_id",nullable=false) private UUID bookingId; @Column(nullable=false) private String provider; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus status; @Column(nullable=false) private BigDecimal amount; @Column(name="provider_transaction_id") private String providerTransactionId; @Column(name="checkout_url",columnDefinition="text") private String checkoutUrl; @Column(name="qr_payload",columnDefinition="text") private String qrPayload; @Column(columnDefinition="text") private String deeplink; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="paid_at") private Instant paidAt; @Column(name="loyalty_points_awarded",nullable=false) private Integer loyaltyPointsAwarded;
 @PrePersist void pre(){if(id==null)id=UUID.randomUUID(); if(createdAt==null)createdAt=Instant.now(); if(status==null)status=PaymentStatus.PENDING; if(loyaltyPointsAwarded==null)loyaltyPointsAwarded=0;}
 public UUID getId(){return id;} public void setId(UUID id){this.id=id;} public UUID getBookingId(){return bookingId;} public void setBookingId(UUID bookingId){this.bookingId=bookingId;} public String getProvider(){return provider;} public void setProvider(String provider){this.provider=provider;} public PaymentStatus getStatus(){return status;} public void setStatus(PaymentStatus status){this.status=status;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal amount){this.amount=amount;} public String getProviderTransactionId(){return providerTransactionId;} public void setProviderTransactionId(String providerTransactionId){this.providerTransactionId=providerTransactionId;} public String getCheckoutUrl(){return checkoutUrl;} public void setCheckoutUrl(String checkoutUrl){this.checkoutUrl=checkoutUrl;} public String getQrPayload(){return qrPayload;} public void setQrPayload(String qrPayload){this.qrPayload=qrPayload;} public String getDeeplink(){return deeplink;} public void setDeeplink(String deeplink){this.deeplink=deeplink;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} public Instant getPaidAt(){return paidAt;} public void setPaidAt(Instant paidAt){this.paidAt=paidAt;} public Integer getLoyaltyPointsAwarded(){return loyaltyPointsAwarded;} public void setLoyaltyPointsAwarded(Integer loyaltyPointsAwarded){this.loyaltyPointsAwarded=loyaltyPointsAwarded;}
}
